const fs = require('fs/promises');
const path = require('path');
const env = require('../../config/env');

// Upload storage on local disk (FEAT-042): a Docker volume on the Oracle
// VM. Same small interface an S3 version would implement (put/get), so it
// can be swapped without touching callers. Keys are generated by
// uploadService (uuid + extension), never taken from the client, and are
// still checked here so nothing can escape the upload directory.
const SAFE_KEY = /^[0-9a-f-]{36}\.(jpg|png)$/;

function pathFor(key) {
  if (!SAFE_KEY.test(key)) throw new Error(`Refusing unsafe storage key: ${key}`);
  return path.join(env.uploads.dir, key);
}

async function put(key, buffer) {
  await fs.mkdir(env.uploads.dir, { recursive: true });
  await fs.writeFile(pathFor(key), buffer, { flag: 'wx' }); // never overwrite
}

async function get(key) {
  try {
    return await fs.readFile(pathFor(key));
  } catch (err) {
    if (err.code === 'ENOENT') return null;
    throw err;
  }
}

async function remove(key) {
  try {
    await fs.unlink(pathFor(key));
  } catch (err) {
    if (err.code !== 'ENOENT') throw err; // already gone is fine
  }
}

module.exports = { put, get, remove };
